// ====== KONFIGURACJA — tu zmieniasz ustawienia ======

// ID konta Instagram (Instagram Business Account ID). Wklej po konfiguracji aplikacji Meta.
const IG_ID = 'WKLEJ_TU_IG_ID';

// Model lokalny (Ollama). gemma2:9b pisze najlepszą polszczyznę z tych, które masz.
const MODEL = 'gemma2:9b';

// Temat posta. Później zamienimy to na automatyczne trendy.
const TOPIC = 'Temat posta: dlaczego małe firmy tracą pieniądze, prowadząc social media ręcznie, i co realnie zmienia automatyzacja.';

// ====== INSTRUKCJA DLA MODELU ======
const SYSTEM = `Jesteś starszym copywriterem polskiej agencji kreatywnej ZOVU z Katowic.
ZOVU tworzy strony internetowe, wideo, treści, reklamy i automatyzacje AI dla małych i średnich firm.

ZASADY JĘZYKA — najważniejsze:
- Piszesz wyłącznie po polsku, poprawną polszczyzną.
- OBOWIĄZKOWO używasz polskich znaków diakrytycznych: ą, ć, ę, ł, ń, ó, ś, ź, ż.
- Zero anglicyzmów i zero kalek z angielskiego.
- Ton: konkretny, rzeczowy, bez korporacyjnej waty i bez wykrzykników. Mówisz jak praktyk do właściciela firmy.

Zwróć WYŁĄCZNIE obiekt JSON o dokładnie takich polach:
{
  "eyebrow": "krótka etykieta WIELKIMI LITERAMI, maksymalnie 24 znaki, na przykład: ZOVU · AUTOMATYZACJA",
  "title": "nagłówek na obrazek, od 40 do 65 znaków, mocny i konkretny, bez kropki na końcu",
  "bullets": ["dokładnie trzy punkty, każdy od 35 do 55 znaków, konkretna korzyść, bez kropki na końcu"],
  "caption": "opis pod post na Instagramie, od 350 do 600 znaków, od dwóch do czterech akapitów rozdzielonych podwójną nową linią, na końcu jedno pytanie do odbiorcy, w całym tekście maksymalnie dwa emoji",
  "hashtags": ["maksymalnie pięć hashtagów po polsku, bez znaku #, bez wymyślonych słów"]
}`;

return [{
  json: {
    ig_id: IG_ID,
    model: MODEL,
    topic: TOPIC,
    system: SYSTEM,
  },
}];

// Sprawdzamy, co przysłał model, i sklejamy gotowy post.
const cfg = $('Konfiguracja').first().json;
const raw = $input.first().json;

let out;
try {
  out = JSON.parse(raw.message.content);
} catch (e) {
  throw new Error('Model nie zwrócił poprawnego JSON. Uruchom jeszcze raz. Surowa odpowiedź: ' + String(raw.message && raw.message.content).slice(0, 300));
}

const clean = (s) => String(s || '').replace(/\s+/g, ' ').replace(/[.\s]+$/, '').trim();

const title = clean(out.title);
if (!title) throw new Error('Brak pola title');

// dokładnie trzy punkty, każdy do 48 znaków — dłuższe łamią się na dwie linie na obrazku
const bullets = (Array.isArray(out.bullets) ? out.bullets : [])
  .map(clean)
  .filter(Boolean)
  .slice(0, 3)
  .map((b) => {
    if (b.length <= 48) return b;
    const cut = b.slice(0, 48);
    const sp = cut.lastIndexOf(' ');
    return (sp > 28 ? cut.slice(0, sp) : cut).trim();
  });

// maksymalnie pięć hashtagów, bez śmieci i bez duplikatów
const hashtags = [...new Set((Array.isArray(out.hashtags) ? out.hashtags : [])
  .map((h) => String(h).replace(/^#/, '').replace(/[^\p{L}\p{N}]/gu, '').toLowerCase())
  .filter((h) => h.length >= 4 && h.length <= 24))]
  .slice(0, 5);

const caption = String(out.caption || '').trim()
  + '\n\n'
  + hashtags.map((h) => '#' + h).join(' ');

return [{
  json: {
    ig_id: cfg.ig_id,
    eyebrow: (clean(out.eyebrow) || 'ZOVU · AI & MARKETING').slice(0, 28),
    title,
    bullets,
    caption,
    footer: 'zovu.pl',
  },
}];
